def reverse_string(s):
    left, right = 0, len(s) - 1
    while left < right:
        s[left], s[right] = s[right], s[left]
        left += 1
        right -= 1

def reversed_copy(s):
    result = list(s)
    reverse_string(result)
    return result

def reverse_blocks(s, k):
    if k <= 0:
        raise ValueError("k must be positive")
    chars = list(s)
    for start in range(0, len(chars), 2 * k):
        left, right = start, min(start + k, len(chars)) - 1
        while left < right:
            chars[left], chars[right] = chars[right], chars[left]
            left += 1
            right -= 1
    return "".join(chars)

def replace_digits(s):
    extra = 5 * sum("0" <= c <= "9" for c in s)
    chars = list(s) + [""] * extra
    read, write = len(s) - 1, len(chars) - 1
    while read >= 0:
        c = chars[read]
        if "0" <= c <= "9":
            for replacement in reversed("number"):
                chars[write] = replacement
                write -= 1
        else:
            chars[write] = c
            write -= 1
        read -= 1
    return "".join(chars)

