def rotate_right(s, k):
    if k < 0:
        raise ValueError("k must be nonnegative")
    if not s:
        return s
    k %= len(s)
    chars = list(s)
    def reverse(left, right):
        while left < right:
            chars[left], chars[right] = chars[right], chars[left]
            left += 1
            right -= 1
    reverse(0, len(chars) - 1)
    reverse(0, k - 1)
    reverse(k, len(chars) - 1)
    return "".join(chars)

def prefix_table(pattern):
    pi = [0] * len(pattern)
    j = 0
    for i in range(1, len(pattern)):
        while j and pattern[i] != pattern[j]:
            j = pi[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
        pi[i] = j
    return pi

def find_substring(text, pattern):
    if not pattern:
        return 0
    pi = prefix_table(pattern)
    j = 0
    for i, c in enumerate(text):
        while j and c != pattern[j]:
            j = pi[j - 1]
        if c == pattern[j]:
            j += 1
        if j == len(pattern):
            return i - len(pattern) + 1
    return -1

def repeated_substring(s):
    if not s:
        return False
    pi = [0] * len(s)
    j = 0
    for i in range(1, len(s)):
        while j and s[i] != s[j]:
            j = pi[j - 1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j
    border = pi[-1]
    period = len(s) - border
    return border > 0 and len(s) % period == 0

