from collections import deque

class MyStack:
    def __init__(self):
        self.queue = deque()

    def push(self, x):
        old_size = len(self.queue)
        self.queue.append(x)
        for _ in range(old_size):
            self.queue.append(self.queue.popleft())

    def pop(self):
        if not self.queue:
            raise IndexError("empty stack")
        return self.queue.popleft()

    def top(self):
        if not self.queue:
            raise IndexError("empty stack")
        return self.queue[0]

    def empty(self):
        return not self.queue

def stack_demo():
