        s.push(x)
    return [s.top(), s.pop(), s.pop(), s.pop(), s.empty()]

def valid_parentheses(s):
    closing = {"(": ")", "[": "]", "{": "}"}
    stack = []
    for c in s:
        if c in closing:
            stack.append(closing[c])
        elif c in ")]}":
            if not stack or stack.pop() != c:
                return False
        else:
            return False
    return not stack

def remove_adjacent_duplicates(s):
    stack = []
    for c in s:
        if stack and stack[-1] == c:
            stack.pop()
        else:
            stack.append(c)
    return "".join(stack)

def evaluate_rpn(tokens):
    stack = []
    for token in tokens:
        if token not in {"+", "-", "*", "/"}:
            stack.append(int(token))
            continue
        if len(stack) < 2:
            raise ValueError("missing operands")
        right, left = stack.pop(), stack.pop()
        if token == "+":
            value = left + right
        elif token == "-":
            value = left - right
        elif token == "*":
            value = left * right
        else:
            value = abs(left) // abs(right)
            if (left < 0) != (right < 0):
                value = -value
        stack.append(value)
    if len(stack) != 1:
        raise ValueError("invalid expression")
    return stack[0]

from collections import deque

def sliding_max(nums, k):
    if not 1 <= k <= len(nums):
        raise ValueError("invalid window size")
    candidates = deque()
    result = []
    for i, value in enumerate(nums):
        while candidates and candidates[0] <= i - k:
            candidates.popleft()
        while candidates and nums[candidates[-1]] <= value:
            candidates.pop()
        candidates.append(i)
        if i >= k - 1:
            result.append(nums[candidates[0]])
    return result

