def next_greater_indices(nums):
    answer = [-1] * len(nums)
    stack = []
    for i, value in enumerate(nums):
        while stack and nums[stack[-1]] < value:
            answer[stack.pop()] = i
        stack.append(i)
    return answer

def daily_temperatures(temperatures):
    answer = [0] * len(temperatures)
    stack = []
    for i, temperature in enumerate(temperatures):
        while stack and temperatures[stack[-1]] < temperature:
            old = stack.pop()
            answer[old] = i - old
        stack.append(i)
    return answer

def next_greater_subset(nums1, nums2):
    greater = {}
    stack = []
    for value in nums2:
        while stack and stack[-1] < value:
            greater[stack.pop()] = value
        stack.append(value)
    return [greater.get(value, -1) for value in nums1]

def next_greater_circular(nums):
    n = len(nums)
    if n == 0:
        return []
    answer = [-1] * n
    stack = []
    for step in range(2 * n):
        i = step % n
        while stack and nums[stack[-1]] < nums[i]:
            answer[stack.pop()] = nums[i]
        if step < n:
            stack.append(i)
    return answer

def largest_rectangle_reference(heights):
    best = 0
    for left in range(len(heights)):
        minimum = heights[left]
        for right in range(left, len(heights)):
            minimum = min(minimum, heights[right])
            best = max(best, minimum * (right - left + 1))
    return best
